                var v = matBT[j];

                lstTh.add(new Thread(() -> {
                    result[i][j] = MyUtil.getScalarProduct(u, v);
                }));
            })
        );


        for (var th : lstTh)
            th.start();

        for (var th : lstTh)
            th.join();


        return result;
    }

